package wgmodern;
import java.util.*;import com.google.gson.*;import net.minecraft.core.RegistryAccess;import net.minecraft.network.FriendlyByteBuf;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.SimpleContainer;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.*;import net.minecraft.world.level.Level;
/** Datapack replacement for the old MineTweaker affinity/aversion add/remove methods. */
public class GemAffinityRecipe implements Recipe<SimpleContainer> {
 public final ResourceLocation id;public final Ingredient ingredient;public final GemAffinities.Definition definition;public final boolean enabled;public final int priority;private final JsonObject json;
 public GemAffinityRecipe(ResourceLocation id,JsonObject json){this.id=id;this.json=json.deepCopy();ingredient=Ingredient.fromJson(json.get("ingredient"));definition=new GemAffinities.Definition(aspects(json,"affinities"),aspects(json,"aversions"));enabled=!json.has("enabled")||json.get("enabled").getAsBoolean();priority=json.has("priority")?json.get("priority").getAsInt():0;}
 private static Set<String> aspects(JsonObject o,String key){var result=new LinkedHashSet<String>();if(o.has(key))for(var e:o.getAsJsonArray(key)){var a=e.getAsString();if(!GemRules.PRIMALS.contains(a))throw new IllegalArgumentException("Gem affinity must be primal: "+a);result.add(a);}return Collections.unmodifiableSet(result);}
 @Override public boolean matches(SimpleContainer c,Level l){return ingredient.test(c.getItem(0));}@Override public ItemStack assemble(SimpleContainer c,RegistryAccess r){return ItemStack.EMPTY;}@Override public ItemStack getResultItem(RegistryAccess r){return ItemStack.EMPTY;}@Override public boolean canCraftInDimensions(int w,int h){return false;}@Override public boolean isSpecial(){return true;}@Override public ResourceLocation getId(){return id;}@Override public RecipeType<?> getType(){return Content.GEM_AFFINITIES.get();}@Override public RecipeSerializer<?> getSerializer(){return Content.GEM_AFFINITY_SERIALIZER.get();}
 public static class Serializer implements RecipeSerializer<GemAffinityRecipe>{public GemAffinityRecipe fromJson(ResourceLocation id,JsonObject j){return new GemAffinityRecipe(id,j);}public GemAffinityRecipe fromNetwork(ResourceLocation id,FriendlyByteBuf b){return fromJson(id,JsonParser.parseString(b.readUtf(32767)).getAsJsonObject());}public void toNetwork(FriendlyByteBuf b,GemAffinityRecipe r){b.writeUtf(r.json.toString(),32767);}}
}
